      if (yil === 2026) { const ytd = 0.843; const p50 = Math.round(s.p50 * ytd), p90 = Math.round(s.p90 * ytd); return { yil, n: s.n, durum: "cari_yil", ytd_pay: ytd, gerceklesen_kwh: kwh, p50_kwh: p50, p90_kwh: p90, oran_p50: +(kwh / p50).toFixed(3), oran_p90: +(kwh / p90).toFixed(3), konum: kwh >= p50 ? "ustu" : kwh >= p90 ? "arasi" : "alti", butce_orani: +(kwh / (24000000 * ytd)).toFixed(3) }; }
